//! @fls: hax_refinement
//! @title: The Refinement trait constructing and projecting a refined value
//! @lean(tier): supported
//! @lean(reason): aeneas fails on the implementations that `#[refinement_type]` generates for the newtype (`Missing trait impl` and `Could not convert the name to a pattern` on `hax__autogenerated_refinement__`); the refinement section of the input-language reference.

// The hax-lib API under test exists only in hax mode.
#![cfg(hax)]

use hax_lib::Refinement;

#[hax_lib::refinement_type(|x| x % 2 == 0)]
pub struct Even(u32);

pub fn halve(e: Even) -> u32 {
    e.get() / 2
}

#[hax_test::equiv]
pub fn constructed_and_projected() -> bool {
    let e = Even::new(8);
    halve(e) == 4
}
